/* Real DOM/events; only native WebView and clipboard I/O are synthetic. */
const {chromium}=require('./playwright-runtime.cjs');
const assert=require('node:assert/strict'),path=require('node:path'),fs=require('node:fs');
const url='file:///'+path.resolve(__dirname,'index.html').replaceAll('\\','/');
const profileId='a'.repeat(32),otherId='b'.repeat(32),tests=[];
const test=(name,run)=>tests.push({name,run});
async function setup(browser,theme='dark'){
 const page=await browser.newPage({viewport:{width:1366,height:768}});page.setDefaultTimeout(2200);
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.addInitScript(({theme,profileId,otherId})=>{
  window.sent=[];window.held=[];window.copied='';window.fx={selected:'',stamp:1,preflight:'ok',changes:[],applyStatus:'completed',hold:'',heap:6,diagnosticMode:'findings',copyFailure:false};
  window.pollCallbacks=[];window.setInterval=f=>{pollCallbacks.push(f);return pollCallbacks.length;};
  const base={id:profileId,name:'建造夜',targetKind:'normal',targetId:'',mods:['base'],heapGiB:8,shaderId:'normal',settings:{'viewpoint-live.properties|mouse.invertY':'false'}};
  const second={...base,id:otherId,name:'另一配置',heapGiB:null};
  window.fx.profiles=[base,second];
  let receive;
  const recovery={pending:false,state:'none',stamp:'',canRecover:false,locations:[],warnings:[]};
  const stamp=()=>String(fx.stamp);
  const answer=m=>{if(fx.failure===m.action){receive({data:{id:m.id,ok:false,error:'查询失败 · 合成示例'}});return;}let data;
   switch(m.action){
    case'status':data={gamePath:fx.gamePath||'Fixture Game',validGame:true,running:!!fx.running,theme,configStamp:fx.configStamp||'config-1',configured:true,buddyFiles:true,components:fx.components||[{id:'base',item:'3809306528',title:'Original Viewpoint',configured:true,downloaded:fx.localFound!==false,version:'42',sourceState:'same',runtimeState:'下次启动启用'}],task:{active:false}};break;
    case'playProfiles':data={stamp:stamp(),selectedId:fx.selected,profiles:fx.profiles.map(p=>({id:p.id,name:p.name,targetKind:p.targetKind,targetId:p.targetId,modCount:p.mods.length,updated:'2026-10-15T00:00:00Z'})),selectedProfile:fx.profiles.find(p=>p.id===fx.selected)||null,pendingRecovery:fx.recovery||recovery,warnings:[],...fx.profileReadPatch};break;
    case'playProfileSelect':fx.selected=m.payload.id;fx.stamp++;data={stamp:stamp(),selectedId:fx.selected,profile:fx.profiles.find(p=>p.id===fx.selected)||null,message:'已选择；未写游戏'};break;
    case'playProfilePreview':data={stamp:stamp(),previewStamp:'preview-'+fx.stamp,profile:fx.profiles.find(p=>p.id===m.payload.id),canApply:!fx.previewError,changes:fx.changes,warnings:[],errors:fx.previewError?[fx.previewError]:[],pendingRecovery:fx.recovery||recovery};break;
    case'playProfileApply':data={status:fx.applyStatus,message:fx.applyStatus==='completed'?'配置已应用':'外部配置已改变',profileId:m.payload.id,recoveryPending:false,pendingRecovery:recovery};if(fx.applyStatus==='completed'){fx.changes=[];fx.heap=8;}break;
    case'playProfileCapture':{const p={...base,id:'c'.repeat(32),name:m.payload.name,targetKind:m.payload.targetKind,targetId:m.payload.targetId};fx.profiles.push(p);fx.stamp++;data={stamp:stamp(),profile:p,summary:{id:p.id,name:p.name,targetKind:p.targetKind,targetId:p.targetId,modCount:1,updated:'2026-10-15T00:00:00Z'},warnings:[]};break;}
    case'playProfileSave':{const p={...m.payload};delete p.stamp;p.id=p.id||'d'.repeat(32);fx.profiles=fx.profiles.filter(x=>x.id!==p.id).concat(p);fx.stamp++;data={stamp:stamp(),profile:p,summary:{id:p.id,name:p.name,targetKind:p.targetKind,targetId:p.targetId,modCount:p.mods.length,updated:'2026-10-15T00:00:00Z'},warnings:[]};break;}
    case'playProfileDelete':fx.profiles=fx.profiles.filter(p=>p.id!==m.payload.id);if(fx.selected===m.payload.id)fx.selected='';fx.stamp++;data={stamp:stamp(),selectedId:fx.selected,message:'已删除'};break;
    case'playProfileExport':data={json:'{"format":"OrangePlayProfile","version":1,"name":"共享","mods":["missing"],"heapGiB":null,"shaderId":"normal","settings":{}}',warnings:[]};break;
    case'playProfileImport':{let parsed;try{parsed=JSON.parse(m.payload.json);}catch{}if(!parsed||parsed.version!==1||parsed.path||parsed.password){receive({data:{id:m.id,ok:false,error:'不支持的分享格式或字段'}});return;}const p={...base,id:'e'.repeat(32),name:parsed.name,targetKind:'normal',targetId:'',mods:parsed.mods};fx.profiles.push(p);fx.stamp++;data={stamp:stamp(),profile:p,summary:{id:p.id,name:p.name,targetKind:'normal',targetId:'',modCount:p.mods.length,updated:'2026-10-15T00:00:00Z'},warnings:['待核实模组 missing']};break;}
    case'playProfileRecover':data={status:'recovered',message:'已恢复',profileId:profileId,recoveryPending:false,pendingRecovery:recovery};fx.recovery=recovery;break;
    case'launchPreflight':{const names=['activity','recovery','workshop','launch-config','launch-guard','mods','java-approvals','memory'],routes=['home','maintenance','maintenance','components','maintenance','mods','java','memory'];data={canLaunch:fx.preflight!=='blocked',checkedUtc:'2026-10-15T00:00:00Z',items:names.map((id,i)=>({id,title:id,status:fx.preflight==='blocked'&&i===3?'error':fx.preflight==='warning'&&i===6?'warning':'ok',message:fx.preflight==='blocked'&&i===3?'缺少 Buddy 启动文件':fx.preflight==='warning'&&i===6?'Java 授权尚未核实':'已核对',route:routes[i]})),message:'请在游戏中核对结果'};break;}
    case'launch':case'profileLaunch':data={message:'启动请求已发送，等待游戏确认'};break;
    case'memoryGet':data={currentGiB:fx.heap,totalGiB:32,availableGiB:12,maximumGiB:24,recommendedGiB:8,stamp:'memory-1'};break;
    case'memorySave':fx.heap=m.payload.value;data={message:'内存已保存'};break;
    case'shadersGet':data={selected:fx.shader||'normal',stamp:'shader-1',packs:[{id:'normal',name:'原版光影',valid:true,file:'normal'},{id:'night',name:'Native fixture night',valid:true,file:'night'}]};break;
    case'shaderSelect':fx.shader=m.payload.id;data={message:'光影已保存'};break;
    case'settingsGet':data={stamp:'settings-1',rows:[{key:'viewpoint-live.properties|mouse.invertY',name:'反转视角',group:'视角',kind:'bool',editable:true,value:fx.settingValue||'false',choices:['true','false'],description:'实际已有参数'}],warnings:[]};break;
    case'settingsSave':fx.settingValue=m.payload.values['viewpoint-live.properties|mouse.invertY'];data={message:'参数已保存'};break;
    case'modProfiles':data={stamp:'mods-1',profiles:[{id:'p1',name:'旧模组清单',modCount:1,updated:'2026-10-15'}],activeMods:fx.defaultMods||['base']};break;
    case'modProfileActivate':fx.defaultMods=['base','extra'];data={message:'默认清单已保存'};break;
    case'modProfileGet':data={id:'p1',name:'旧模组清单',stamp:'mods-1',mods:fx.legacyMods||['base']};break;
    case'modCatalog':data={mods:fx.catalog||[{id:'base',name:'Foundation',title:'Foundation',author:'原作者',version:'42',source:'local',requires:[],conflict:false,map:false,componentManaged:false},{id:'extra',name:'Extra',title:'Extra',author:'原作者',version:'42',source:'workshop',workshopId:'124',requires:['base'],conflict:false,map:false,componentManaged:false},{id:'missing',name:'Needs missing',title:'Needs missing',author:'原作者',version:'42',source:'local',requires:['absent'],conflict:false,map:false,componentManaged:false}],warnings:[]};break;
    case'modCover':data={token:m.payload.token,cover:fx.cover??'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6ZyAAAAAASUVORK5CYII='};break;
    case'savesList':data={saves:fx.saves||[{id:'Sandbox/Test',name:'测试存档',mode:'Sandbox',editable:true,modifiedUtc:'2026-10-15T00:00:00Z',modCount:fx.saveMods?.length??1}],warnings:[]};break;
    case'saveDeletePreview':{assertPayload(['id']);const s=(fx.saves||[]).find(s=>s.id===m.payload.id);if(!s)throw new Error('Unknown synthetic save');data={id:s.id,name:s.name,mode:s.mode,path:'C:\\SyntheticSaves\\'+s.id.replaceAll('/','\\'),stamp:'saveDelete:'+'a'.repeat(64)};break;}
    case'saveDelete':{assertPayload(['id','stamp','confirmed']);if(m.payload.stamp!=='saveDelete:'+'a'.repeat(64)||m.payload.confirmed!==true)throw new Error('Bad synthetic delete contract');fx.saves=fx.saves.filter(s=>s.id!==m.payload.id);data={status:'completed',id:m.payload.id,message:'已移入回收站'};break;}
    case'componentsAction':data={message:fx.restoreMessage||'基础组件已恢复。',status:fx.restoreStatus||'completed'};if(fx.failRefresh)fx.failure='status';break;
    case'saveGet':data={id:m.payload.id,name:'测试存档',mode:'Sandbox',stamp:'save-1',enabled:fx.saveMods||['base'],maps:[],requiresConfirmation:false,warnings:[]};break;
    case'saveSave':fx.saveMods=m.payload.mods;data={message:'存档清单已保存'};break;
    case'saveThumb':case'serverThumb':data={id:m.payload.id,dataUrl:fx.thumb||null,message:'没有精确匹配的原版缩略图'};break;
    case'serverList':data={stamp:'server-1',servers:fx.serverDeleted?[]:[{id:'s1',name:fx.serverName||'已保存测试服务器',host:'example.invalid',port:16261,queryPort:0,username:'',hasUserPassword:true,hasServerPassword:true,useSteamRelay:false,description:'私人备注'}]};break;
    case'serverUpsert':fx.serverName=m.payload.name;data={message:'服务器已保存'};break;
    case'serverDelete':fx.serverDeleted=true;data={message:'服务器已删除'};break;
    case'javaList':data={supported:true,stamp:'java-1',jars:[],warnings:[]};break;
    case'playtimeGet':data={todaySeconds:0,totalSeconds:0,running:false,sessionSeconds:0,reminderMinutes:0,reminderDue:false,tracking:'stopped',message:'未运行'};break;
    case'help':data={message:'Synthetic help'};break;
    case'coreUpdateStatus':data={protocol:1,revision:1,state:'Idle',currentVersion:'1.2.0'};break;
    case'gameDiagnostics':data={checkedUtc:'2026-10-15T00:00:00Z',findings:fx.diagnosticMode==='empty'?[]:[{id:'java-heap-exhausted',severity:'error',confidence:'confirmed',title:'Java 堆内存不足',message:'已观察到错误，原因仍需核对',evidence:['java.lang.OutOfMemoryError [redacted]'],source:'console',historical:true,nextStep:'核对总内存预算'}],warnings:[{id:'source-age-unknown',source:'console',message:'时间未核实'}],sources:[{id:'console',kind:'game-log',label:'游戏控制台日志',modifiedUtc:'',newestEvidenceUtc:'',freshness:'unknown',status:'read',encoding:'utf-8',bytesRead:100,historical:true,truncated:false}],reportText:'脱敏报告\njava.lang.OutOfMemoryError [redacted]'};break;
    case'logs':data={text:'工具日志'};break;
    case'updatesGet':data={checkedUtc:'2026-10-15T00:00:00Z',items:[{item:'124',state:'available',local:'1',remote:'2'}],message:'仅元数据检查'};break;
    case'theme':data={message:'主题已保存'};break;
    case'steamSubscriptions':data={items:[{id:'999',title:'Uncovered original item',subscribed:true,downloaded:false,needsUpdate:false}],message:'Synthetic metadata only'};break;
    default:data={message:'Synthetic '+m.action};
   }receive({data:{id:m.id,ok:true,data}});
   function assertPayload(keys){if(JSON.stringify(Object.keys(m.payload).sort())!==JSON.stringify(keys.sort()))throw new Error('Unexpected synthetic native payload: '+m.action);}
  };
  window.replyNative=answer;
  window.emitNative=data=>receive({data});
  window.chrome={webview:{addEventListener:(_,f)=>receive=f,postMessage:m=>{sent.push(m);if(fx.hold===m.action)held.push(m);else queueMicrotask(()=>answer(m));}}};
  Object.defineProperty(navigator,'clipboard',{value:{writeText:async text=>{if(fx.copyFailure)throw new Error('Clipboard denied');window.copied=text;}}});
 },{theme,profileId,otherId});
 await page.goto(url);await page.waitForFunction(()=>!!orange.state.status);await openHomeSections(page);return{page,errors};
}
async function openHomeSections(page){await page.locator('[data-home-manage],[data-home-details]').evaluateAll(es=>es.forEach(e=>e.open=true));}
async function route(page,name){await page.evaluate(n=>location.hash=n,name);await page.waitForFunction(n=>document.querySelector('#page').dataset.route===n,name);if(name==='home')await openHomeSections(page);}
async function selected(page){await page.locator('#play-profile-select').selectOption(profileId);await page.waitForFunction(()=>fx.selected==='a'.repeat(32));}
const actions=page=>page.evaluate(()=>sent.map(m=>m.action));
test('selecting a home profile never applies game settings',async b=>{const{page}=await setup(b);assert.equal(await page.locator('#play-profile-select').count(),1);await selected(page);assert.match(await page.locator('[data-current-config]').innerText(),/6 GiB/);assert.match(await page.locator('[data-selected-profile]').innerText(),/建造夜/);assert.equal((await actions(page)).some(a=>['playProfileApply','launch','profileLaunch','javaSave','componentsAction'].includes(a)),false);assert.equal(await page.getByRole('button',{name:'启动到主菜单',exact:true}).count(),1);await page.close();});
test('blocking preflight prevents launch and offers the correct repair route',async b=>{const{page}=await setup(b);await page.evaluate(()=>fx.preflight='blocked');await page.locator('#launch').click();await page.getByText('缺少 Buddy 启动文件',{exact:true}).waitFor();assert.equal((await actions(page)).includes('launch'),false);await page.locator('[data-preflight-repair="components"]').click();await page.waitForFunction(()=>orange.state.route==='components');await page.close();});
test('advisory launch submits directly while Java review stays an explicit optional action',async b=>{const{page}=await setup(b);await page.evaluate(()=>fx.preflight='warning');await page.locator('#launch').click();await page.waitForFunction(()=>sent.some(m=>m.action==='launch')&&!orange.state.launchAttempt);assert.equal(await page.locator('#confirm[open]').count(),0);await page.locator('.preflight-summary').click();await page.locator('[data-preflight-repair="java"]').click();await page.locator('#java-review[open]').waitFor();await page.locator('[data-java-close]').click();assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='launch').payload),{});assert.equal((await actions(page)).includes('javaSave'),false);await page.close();});
test('save and server launch use native target IDs without credentials',async b=>{for(const[kind,id]of[['save','Sandbox/Test'],['server','s1']]){const{page}=await setup(b);await page.locator('#launch-target-kind').selectOption(kind);await page.locator('#launch-target-id').selectOption(id);await page.locator('#launch').click();await page.waitForFunction(()=>sent.some(m=>m.action==='profileLaunch'));assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='launchPreflight').payload),{targetKind:kind});assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='profileLaunch').payload),{kind,id});assert.equal((await actions(page)).includes('playProfileSelect'),false,'an unselected target needs no redundant store mutation');await page.close();}});
test('changed profile applies only after consent then obtains fresh preflight',async b=>{const{page}=await setup(b);await selected(page);await page.evaluate(()=>fx.changes=[{kind:'setting',key:'viewpoint-live.properties|graphics.mode',before:null,after:'Modern'}]);await page.locator('#launch').click();await page.locator('#confirm[open]').waitFor();assert.match(await page.locator('#confirm-body').innerText(),/原来不存在.*Modern/s);assert.equal((await actions(page)).includes('playProfileApply'),false);await page.locator('#confirm-yes').click();await page.waitForFunction(()=>sent.some(m=>m.action==='launch'));const a=await actions(page);assert.ok(a.indexOf('playProfileApply')<a.indexOf('launchPreflight'));assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='playProfileApply').payload),{id:profileId,previewStamp:'preview-2',confirmed:true});assert.match(await page.locator('[data-current-config]').innerText(),/8 GiB/);await page.close();});
test('stale failed apply ends launch without retry and preserves the selection',async b=>{const{page}=await setup(b);await selected(page);await page.evaluate(()=>{fx.changes=[{kind:'heap',key:'heapGiB',before:6,after:8}];fx.applyStatus='failed';});await page.locator('#launch').click();await page.locator('#confirm-yes').click();await page.getByText('外部配置已改变',{exact:true}).waitFor();assert.equal((await actions(page)).filter(a=>a==='playProfileApply').length,1);assert.equal((await actions(page)).includes('launch'),false);assert.equal(await page.locator('#play-profile-select').inputValue(),profileId);await page.close();});
test('a delayed preview cannot authorize a changed selected profile',async b=>{const{page}=await setup(b);await selected(page);await page.evaluate(()=>fx.hold='playProfilePreview');await page.locator('#launch').click();await page.waitForFunction(()=>held.length===1);await page.locator('#play-profile-select').selectOption(otherId);await page.waitForFunction(()=>fx.selected==='b'.repeat(32));await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForTimeout(50);assert.equal((await actions(page)).includes('launch'),false);assert.equal(await page.locator('#confirm[open]').count(),0);await page.close();});
test('capture persists a new profile without selecting or applying',async b=>{const{page}=await setup(b);await page.locator('[data-play-capture]').click();await page.locator('#play-profile-name').fill('捕获配置');await page.locator('[data-play-capture-confirm]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='playProfileCapture'));assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='playProfileCapture').payload),{stamp:'1',name:'捕获配置',targetKind:'normal',targetId:''});assert.equal(await page.locator('#play-profile-select').inputValue(),'');assert.equal((await actions(page)).includes('playProfileApply'),false);await page.close();});
test('server profile editor has no ordinary mods and saves exact portable local fields',async b=>{const{page}=await setup(b);await selected(page);await page.locator('[data-play-edit]').click();await page.locator('#play-edit-kind').selectOption('server');await page.locator('#play-edit-target').selectOption('s1');await page.locator('[data-play-save]').click();await page.waitForFunction(()=>sent.some(m=>m.action==='playProfileSave'));const p=await page.evaluate(()=>sent.find(m=>m.action==='playProfileSave').payload);assert.deepEqual(p.mods,[]);assert.equal(p.targetId,'s1');assert.deepEqual(Object.keys(p).sort(),['heapGiB','id','mods','name','settings','shaderId','stamp','targetId','targetKind']);await page.close();});
test('import and export use native portable JSON without auto apply',async b=>{const{page}=await setup(b);await selected(page);await page.locator('[data-play-share]').click();await page.locator('[data-play-export]').click();await page.locator('#play-share-json').waitFor();const json=await page.locator('#play-share-json').inputValue();assert.equal(JSON.parse(json).format,'OrangePlayProfile');assert.doesNotMatch(json,/targetId|password|path|decision/);await page.locator('[data-play-copy]').click();assert.equal(await page.evaluate(()=>copied),json);await page.locator('#play-import-json').fill('{"version":99,"path":"C:/private"}');await page.locator('[data-play-import]').click();await page.locator('#confirm-yes').click();await page.getByText('不支持的分享格式或字段',{exact:true}).waitFor();assert.match(await page.locator('#play-import-json').inputValue(),/private/);await page.locator('#play-import-json').fill(json);await page.locator('[data-play-import]').click();await page.locator('#confirm-yes').click();await page.getByText('待核实模组 missing',{exact:true}).waitFor();assert.equal((await actions(page)).includes('playProfileApply'),false);assert.equal(await page.locator('#play-profile-select').inputValue(),profileId);await page.close();});
test('diagnostics unknown age is distinct from proven history and copies redacted report',async b=>{const{page}=await setup(b);await route(page,'maintenance');await page.locator('[data-diagnostics-read]').click();await page.getByText('Java 堆内存不足',{exact:true}).waitFor();assert.match(await page.locator('[data-diagnostics]').innerText(),/时间未知/);assert.doesNotMatch(await page.locator('[data-diagnostic-finding]').innerText(),/历史记录/);await page.locator('[data-diagnostic-finding] details').click();assert.match(await page.locator('[data-diagnostic-finding]').innerText(),/OutOfMemoryError/);await page.locator('[data-diagnostics-copy]').click();assert.equal(await page.evaluate(()=>copied),'脱敏报告\njava.lang.OutOfMemoryError [redacted]');await page.evaluate(()=>{fx.diagnosticMode='empty';fx.copyFailure=true;});await page.locator('[data-diagnostics-read]').click();await page.getByText(/未发现常见错误记录/).waitFor();await page.locator('[data-diagnostics-copy]').click();await page.getByText(/请手动复制/).waitFor();await page.close();});
test('bulk filters alter only a current ordered draft and unknown updates stay unknown',async b=>{const{page}=await setup(b);await route(page,'mods');await page.locator('[data-mod-profile-open="p1"]').click();await page.locator('[data-mod-filter]').selectOption('disabled');await page.locator('[data-bulk-mod="extra"]').check();await page.locator('[data-bulk-mod="missing"]').check();await page.locator('[data-bulk-add]').click();assert.deepEqual(await page.locator('[data-profile-mod-id]').evaluateAll(es=>es.map(e=>e.dataset.profileModId)),['base','extra','missing']);assert.equal((await actions(page)).some(a=>['modProfileSave','modProfileActivate','steamDownload'].includes(a)),false);await page.locator('[data-mod-filter]').selectOption('updates');assert.match(await page.locator('#profile-mod-catalog').innerText(),/更新状态未知/);await page.close();});
test('unrelated async reads preserve name draft focus caret and scroll',async b=>{const{page}=await setup(b);await route(page,'mods');await page.locator('[data-mod-profile-open="p1"]').click();await page.locator('#mod-profile-name').fill('保留草稿');await page.locator('#mod-profile-name').evaluate(e=>{e.focus();e.setSelectionRange(2,3);document.querySelector('main').scrollTop=180;});await page.evaluate(()=>{fx.hold='modProfiles';});await page.locator('[data-profiles-refresh]').click();await page.locator('#mod-profile-name').focus();await page.locator('#mod-profile-name').evaluate(e=>e.setSelectionRange(2,3));const before=await page.locator('main').evaluate(e=>e.scrollTop);await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForTimeout(40);assert.equal(await page.locator('#mod-profile-name').inputValue(),'保留草稿');assert.equal(await page.locator('#mod-profile-name').evaluate(e=>document.activeElement===e&&e.selectionStart===2&&e.selectionEnd===3),true);assert.equal(await page.locator('main').evaluate(e=>e.scrollTop),before);assert.equal(await page.evaluate(()=>orange.hasUnsavedDrafts()),true);await page.close();});
test('local launch feedback is indeterminate and a handled request never claims game load',async b=>{const{page}=await setup(b);await page.evaluate(()=>fx.hold='launch');await page.locator('#launch').click();await page.waitForFunction(()=>held.length===1);await page.evaluate(()=>chrome.webview.addEventListener);await page.waitForSelector('[data-experience-progress]');assert.equal(await page.locator('[data-experience-progress]').getAttribute('value'),null);assert.equal(await page.locator('#play-profile-select').isEnabled(),true);await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.getByText(/本次已提交目标/).waitFor();assert.doesNotMatch(await page.locator('[data-launch-feedback]').innerText(),/100%|已进入|加载成功|连接成功/);await page.close();});
test('seven groups retain eleven routes and readable semantic statuses in both themes',async b=>{for(const theme of['dark','light']){const{page,errors}=await setup(b,theme);assert.equal(await page.locator('nav[aria-label="主导航"] > button').count(),7);for(const name of['home','components','mods','workshop','saves','servers','shaders','settings','memory','maintenance','help']){await route(page,name);assert.equal(await page.locator('main').evaluate(e=>e.scrollWidth<=e.clientWidth),true,name);assert.equal(await page.locator('body').evaluate(e=>getComputedStyle(e).fontSize),'14px');}await route(page,'home');assert.equal(await page.locator('[data-current-config]').evaluate(e=>parseFloat(getComputedStyle(e).fontSize)>=12),true);assert.deepEqual(errors,[]);await page.close();}});
test('bulk requires explicit native component classification and preserves legacy managed draft IDs',async b=>{const{page}=await setup(b);await page.evaluate(()=>{fx.legacyMods=['Viewpoint','base'];fx.catalog=[{id:'Viewpoint',name:'Same title',source:'local',requires:[],conflict:false,componentManaged:true},{id:'ordinary',name:'Same title',source:'local',requires:[],conflict:false,componentManaged:false},{id:'unverified',name:'Same title',source:'local',requires:[],conflict:false}];});await route(page,'mods');await page.locator('[data-mod-profile-open="p1"]').click();assert.equal(await page.locator('[data-bulk-mod="Viewpoint"]').isDisabled(),true);assert.equal(await page.locator('[data-bulk-mod="unverified"]').isDisabled(),true);await page.locator('[data-bulk-mod="ordinary"]').check();await page.locator('[data-bulk-add]').click();assert.deepEqual(await page.locator('[data-profile-mod-id]').evaluateAll(es=>es.map(e=>e.dataset.profileModId)),['Viewpoint','base','ordinary']);assert.match(await page.locator('#profile-mod-catalog').innerText(),/组件页管理|分类未核实/);await page.close();});
test('a saving full profile locks its submitted editor through the authoritative response',async b=>{const{page}=await setup(b);await selected(page);await page.locator('[data-play-edit]').click();await page.locator('#play-profile-name').fill('保存中草稿');await page.evaluate(()=>fx.hold='playProfileSave');await page.locator('[data-play-save]').click();await page.waitForFunction(()=>held.length===1);assert.equal(await page.locator('#play-profile-name').isDisabled(),true);assert.equal(await page.locator('[data-play-close]').isDisabled(),true);await page.evaluate(()=>{fx.hold='';replyNative(held.shift());});await page.waitForSelector('#play-editor',{state:'detached'});await page.close();});
test('Escape cannot silently lose an unsaved full-profile editor',async b=>{const{page}=await setup(b);await selected(page);await page.locator('[data-play-edit]').click();await page.locator('#play-profile-name').fill('不可丢失');await page.keyboard.press('Escape');await page.locator('#confirm[open]').waitFor();await page.locator('#confirm-no').click();assert.equal(await page.locator('#play-profile-name').inputValue(),'不可丢失');assert.equal(await page.evaluate(()=>orange.hasUnsavedDrafts()),true);await page.locator('[data-play-close]').click();await page.locator('#confirm-yes').click();await page.waitForSelector('#play-editor',{state:'detached'});assert.equal(await page.evaluate(()=>orange.hasUnsavedDrafts()),false);await page.close();});
test('profile recovery uses the native recovery stamp with explicit consent',async b=>{const{page}=await setup(b);await page.evaluate(()=>{fx.recovery={pending:true,state:'recoverable',stamp:'recovery-only',canRecover:true,locations:['启动 JSON'],warnings:['核对恢复证据']};});await page.locator('[data-play-refresh]').click();await page.locator('[data-play-recover]').click();assert.equal((await actions(page)).includes('playProfileRecover'),false);await page.locator('#confirm-yes').click();await page.waitForFunction(()=>sent.some(m=>m.action==='playProfileRecover'));assert.deepEqual(await page.evaluate(()=>sent.find(m=>m.action==='playProfileRecover').payload),{stamp:'recovery-only',confirmed:true});await page.close();});
test('no-change selected profile launches without unnecessary apply and a cached failure can retry',async b=>{const{page}=await setup(b);await selected(page);await page.evaluate(()=>fx.preflight='blocked');await page.locator('#launch').click();await page.getByText('缺少 Buddy 启动文件',{exact:true}).waitFor();await page.evaluate(()=>fx.preflight='ok');await page.locator('#launch').click();await page.waitForFunction(()=>sent.some(m=>m.action==='launch'));assert.equal((await actions(page)).includes('playProfileApply'),false);assert.equal((await actions(page)).filter(a=>a==='launchPreflight').length,2);await page.close();});
test('Escape keeps unimported sharing text until explicit discard',async b=>{const{page}=await setup(b);await page.locator('[data-play-share]').click();await page.locator('#play-import-json').fill('还没导入');await page.keyboard.press('Escape');await page.locator('#confirm[open]').waitFor();await page.locator('#confirm-no').click();assert.equal(await page.locator('#play-import-json').inputValue(),'还没导入');await page.locator('[data-share-close]').click();await page.locator('#confirm-yes').click();assert.equal(await page.evaluate(()=>orange.hasUnsavedDrafts()),false);await page.close();});
